# Coincidencia de patrones con case y nocasematch:
shopt -s nocasematch   # Activa insensibilidad a mayúsculas/minúsculas
case "$1" in
    start|iniciar) echo "Iniciando demonio..." ;;
    stop|parar)    echo "Deteniendo demonio..." ;;
    status)        echo "Estado del demonio: ACTIVO" ;;
    *)             echo "Uso: $0 {start|stop|status}"; exit 1 ;;
esac
shopt -u nocasematch   # Desactiva nocasematch
